custom_css:
/* 雾里来信 · independent modules v2. No script, embedded images, animation or blur. */
:root {
  --wl-ink: #4b3540;
  --wl-line: #795560;
  --wl-paper: #fff6f3;
  --wl-avatar-ratio: 16 / 9;
}
#sheld { background: #f9e8ed !important; box-shadow:none !important; backdrop-filter:none !important; }
#chat { padding:8px !important; background:transparent !important; }
#chat .mes {
  box-sizing:border-box; position:relative; isolation:isolate;
  display:flex !important; flex-direction:column !important; align-items:stretch !important;
  width:100% !important; max-width:none !important; min-width:0 !important;
  margin:12px 0 22px !important; padding:38px 12px 68px !important;
  gap:0 !important; border:0 !important; border-radius:0 !important;
  box-shadow:none !important; backdrop-filter:none !important; color:var(--wl-ink);
  background-color:var(--wl-paper) !important;
  background-image:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/v1/paper.webp') !important;
  background-size:320px 240px !important;
  border:12px solid transparent !important;
  border-image:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/v2/avatar-frame.webp') 65 / 14px / 0 stretch !important;

}
/* Only ornamental overlays: clicks pass through. Their paper is completely transparent. */
#chat .mes::before,#chat .mes::after {
  content:""; position:absolute; left:0; right:0; pointer-events:none; z-index:2;
  background-repeat:no-repeat;
}
#chat .mes::before {
  top:-10px; left:-12px; right:-12px; height:130px;
  background-image:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/v2/rose-left.webp'),url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/v2/rose-right.webp'),url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/v2/moon-header.webp');
  background-size:26% auto,26% auto,48% auto;
  background-position:left 5px,right 5px,center 7px;
}
#chat .mes::after {
  bottom:-5px; left:-12px; right:-12px; height:140px;
  background-image:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/v2/rose-vine-left.webp'),url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/v2/rose-vine-right.webp'),url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/v2/footer-flower-left.webp'),url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/v2/footer-flower-right.webp'),url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/v2/footer-crescent.webp');
  background-size:25% auto,25% auto,24% auto,24% auto,19% auto;
  background-position:left bottom,right bottom,calc(50% - 45px) bottom,calc(50% + 45px) bottom,center bottom;
}
/* Same layout for user and character. Avatar crop/position are left to the crop plugin. */
#chat .mes > .mesAvatarWrapper {
  position:relative !important; display:grid !important;
  grid-template-columns:repeat(3,minmax(0,1fr)); grid-template-rows:auto 27px;
  width:100% !important; max-width:none !important; min-width:0 !important;
  margin:0 !important; padding:0 !important; gap:0 !important; flex:none !important;
  background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/v2/counter-star.webp') 33.3% bottom/10px 12px no-repeat,url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/v2/counter-star.webp') 66.7% bottom/10px 12px no-repeat;
  border-bottom:1px solid #9d7582;

}
/* Independent transparent avatar frame; never part of the avatar pixels. */
#chat .mes > .mesAvatarWrapper::before {
  content:""; position:absolute; inset:-2px -2px 25px; z-index:1; pointer-events:none;
  border:20px solid transparent;
  border-image:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/v2/avatar-frame.webp') 65 / 22px / 0 stretch;
}
#chat .mes > .mesAvatarWrapper > .avatar {
  grid-column:1/-1; grid-row:1; box-sizing:border-box;
  width:100% !important; max-width:none !important; height:auto !important;
  aspect-ratio:var(--wl-avatar-ratio); margin:0 !important; padding:0 !important;
  border:0; border-radius:2px !important; box-shadow:none !important;
}
#chat .mes > .mesAvatarWrapper > .avatar img {
  width:100%; height:100%; border-radius:0; box-shadow:none;
}
#chat .mes .mesIDDisplay,#chat .mes .mes_timer,#chat .mes .tokenCounterDisplay {
  position:static !important; grid-row:2; align-self:center; justify-self:stretch;
  width:auto !important; min-width:0 !important; margin:0 !important; padding:0 !important;
  line-height:27px !important; font-size:11px !important; text-align:center !important;
  white-space:nowrap; color:var(--wl-ink); opacity:1;
}
#chat .mes .mesIDDisplay { grid-column:1; }
#chat .mes .mes_timer { grid-column:2; }
#chat .mes .tokenCounterDisplay { grid-column:3; }
#chat .mes > .mes_block {
  position:relative; display:block !important; box-sizing:border-box; overflow:visible;
  flex:auto !important; width:100% !important; max-width:none !important; min-width:0 !important;
  margin:0 !important; padding:0 0 18px !important; background:transparent !important;
}
/* Short, non-repeating original moon pendants. The long middle stays clear. */
#chat .mes > .mes_block::before,#chat .mes > .mes_block::after {
  content:""; position:absolute; top:4px; width:27px; height:88px; z-index:1;
  pointer-events:none; background-size:contain; background-repeat:no-repeat;
}
#chat .mes > .mes_block::before { left:-13px; background-image:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/v2/pendant-left.webp'); }
#chat .mes > .mes_block::after { right:-13px; background-image:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/v2/pendant-right.webp'); }
#chat .mes .ch_name {
  position:relative; display:flex !important; align-items:center !important; justify-content:center !important;
  width:100%; min-height:36px; margin:0 !important; padding:0 !important;
  border-top:0;
  background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/v2/ribbon.webp') center/160px 36px no-repeat;
}
#chat .mes .ch_name > .flex1 {
  display:flex !important; flex:0 1 135px !important; justify-content:center !important;
  align-items:center !important; min-width:0; text-align:center;
}
#chat .mes .ch_name .alignItemsBaseline {
  display:flex !important; justify-content:center !important; align-items:center !important;
  flex-wrap:wrap; width:100%; min-width:0;
}
#chat .mes .name_text {
  display:block !important; max-width:100%; margin:0 !important; padding:2px 0 !important;
  text-align:center !important; color:var(--wl-ink); font-size:14px; font-weight:400;
  line-height:1.3; overflow-wrap:anywhere; background:none !important;
}
#chat .mes .timestamp { font-size:9px; }
#chat .mes .mes_buttons {
  position:absolute !important; top:calc(100% + 3px); right:0; z-index:3;
  max-width:95%; flex-wrap:wrap; font-size:11px;
}
#chat .mes .mes_text {
  position:relative; box-sizing:border-box; width:100% !important; max-width:none !important;
  min-width:0 !important; margin:0 !important; padding:29px 3px 8px !important;
  min-height:0 !important; background:none !important; line-height:1.8; overflow-wrap:anywhere;
}
#chat .mes .mes_text p { margin:.4em 0 .8em; }
#chat .mes > .for_checkbox { position:absolute; left:0; top:0; }
#chat .mes > .swipe_left { position:absolute; left:8px; bottom:20px; z-index:3; }
#chat .mes > .swipe_right { position:absolute; right:8px; bottom:20px; z-index:3; }
/* Retain a decorative toolbar frame, with no title text. */
#top-bar {
  background-color:#fff1f5 !important;
  background-image:none !important;
  background-position:left center,right center,center !important;
  background-size:auto 100%,auto 100%,320px 240px !important;
  background-repeat:no-repeat,no-repeat,repeat !important;
  border-block:1px solid #99717e !important; box-shadow:none !important; backdrop-filter:none !important;
}
#top-settings-holder > .drawer,#top-settings-holder .drawer-toggle,#top-settings-holder .drawer-icon {
  opacity:1 !important; filter:none !important;
}
#top-settings-holder .drawer-toggle { display:flex !important; align-items:center !important; justify-content:center !important; min-height:36px; }
#top-settings-holder .drawer-icon { display:inline-flex !important; flex:0 0 28px !important; width:28px !important; height:32px !important; min-width:28px !important; min-height:32px !important; align-items:center; justify-content:center; background-position:center !important; background-size:24px 24px !important; background-repeat:no-repeat !important; }
/* Separate paper and transparent flourishes for the input frame. */
#send_form {
  position:relative; background-color:var(--wl-paper) !important;
  background-image:none !important;
  background-position:left center,right center,center !important;
  background-size:auto 100%,auto 100%,320px 240px !important;
  background-repeat:no-repeat,no-repeat,repeat !important;
  border:1px solid #ad8592 !important; border-radius:10px !important;
  padding:7px 10px !important; box-shadow:none !important; backdrop-filter:none !important;
}
#send_textarea { background:transparent !important; color:var(--wl-ink) !important; }
#send_but { align-self:center !important; background-position:center !important; }
/* Hide bars only; do not alter overflow or scrolling. */
:where(*) { scrollbar-width:none; }
::-webkit-scrollbar { width:0; height:0; display:none; }
@media(min-width:700px) {
  #chat .mes { padding-top:64px !important; padding-bottom:100px !important; padding-inline:24px !important; }
  #chat .mes::before { background-size:150px auto,150px auto,240px auto; background-position:left 5px,right 5px,center 0; }
  #chat .mes::after { background-size:170px auto,170px auto,80px auto,80px auto,96px auto; }
}

